 private function types(array $r):array{$names=['0'=>'GNRE Simples','1'=>'Múltiplos documentos de origem','2'=>'Múltiplas receitas'];$o=[];foreach((array)$r['uf_types'] as $v)if(isset($names[$v]))$o[]=['code'=>$v,'description'=>$names[$v]];return$o;} private function receipts(array $r,string $t):array{$o=[];foreach((array)$r['receipts'] as $x)if(in_array($t,(array)($x['types']??[]),true))$o[]=['code'=>(string)$x['code'],'description'=>(string)$x['description']];return$o;} private function yesno():array{return [['code'=>'yes','description'=>'Sim'],['code'=>'no','description'=>'Não']];} private function ids():array{return [['code'=>'CNPJ','description'=>'CNPJ'],['code'=>'CPF','description'=>'CPF'],['code'=>'IE','description'=>'Inscrição estadual']];} private function months():array{$o=[];for($i=1;$i<=12;$i++)$o[]=['code'=>str_pad((string)$i,2,'0',STR_PAD_LEFT),'description'=>str_pad((string)$i,2,'0',STR_PAD_LEFT)];return$o;} private function extra(string $t):string{$t=strtoupper($t);return strpos($t,'DATA')!==false?'date':(strpos($t,'DEC')!==false||strpos($t,'NUM')!==false?'currency':'text');} private function emissionDateExtra(array $extra):bool{$title=mb_strtolower(trim((string)($extra['title']??'')),'UTF-8');$title=strtr($title,['á'=>'a','à'=>'a','ã'=>'a','â'=>'a','é'=>'e','ê'=>'e','í'=>'i','ó'=>'o','ô'=>'o','õ'=>'o','ú'=>'u','ç'=>'c']);return $title==='data de emissao';}
